def regrouper_doublons(apps, schema_editor):
    """Une seule ligne réservable par station et par type : les doublons approuvés sont regroupés."""
    Transport = apps.get_model("mobilite", "Transport")
    gardes = {}
    for t in Transport.objects.filter(statut="approuve").order_by("created_at", "pk"):
        cle = (t.station_id, t.type)
        if cle not in gardes:
            gardes[cle] = t
            continue
        garde = gardes[cle]
        garde.unites_disponibles += t.unites_disponibles
        garde.save(update_fields=["unites_disponibles"])
        t.fusionne = True
        t.save(update_fields=["fusionne"])


